#!/usr/bin/env bash\nset -euo pipefail\n\n# Create temporary hosts structure\nTMP_HOSTS=$(mktemp -d)\nmkdir -p "$TMP_HOSTS"/hostA "$TMP_HOSTS"/hostB\n\nOLD_FP="oldkey123"\nOLD_LINE="ssh-ed25519 AAAAC3... $OLD_FP user@example.com"\n\necho "$OLD_LINE" > "$TMP_HOSTS"/hostA/authorized_keys\necho "$OLD_LINE" > "$TMP_HOSTS"/hostB/authorized_keys\n\n# Locate the script\nSCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)\n\n# Run the rotator\n"$SCRIPT_DIR"/rotate_ssh_key.sh "$OLD_FP" "$TMP_HOSTS"\n\n# Verify old key removed and new key added\nfor AUTH in "$TMP_HOSTS"/*/authorized_keys; do\n  if grep -q "$OLD_FP" "$AUTH"; then\n    echo "FAIL: old key still present in $AUTH"\n    exit 1\n  fi\n  if ! grep -q "nightly-ssh-key-rotator" "$AUTH"; then\n    echo "FAIL: new key not added in $AUTH"\n    exit 1\n  fi\n done\n\necho "All tests passed."\nexit 0\n
